-- Sprint 1c (D-041): the Systems page's hero image is replaced on the owner's request — interlocking graphite modules with orange light seams instead of the circuit board. The first version is kept, superseded (BR-1.17).
-- Generated by scripts/build-hero-photos.mjs --replace; the encoded image(s) are in design/hero/. The slot's current
-- photo is superseded (BR-1.17: kept, never altered or deleted) and the new one becomes current — the owner can replace
-- it in Admin → Photos at any time. Additive only.


UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-systems' AND "supersededAt" IS NULL AND "sha256" <> 'e4d5a54a275349fb775c625472f5e3121ae7898f83bb8491b115628b4615da10';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-systems', 'A decorative image behind the top of the page', 'image/webp', 1280, 853, 39828, 'e4d5a54a275349fb775c625472f5e3121ae7898f83bb8491b115628b4615da10', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-systems' AND "supersededAt" IS NULL);
